	/**
	 * Method to retrieve the ImagingReport via ImagingReportFetchOneSummary
	 * @param 	summary ImagingReportFetchOneSummary
	 * @return 	ImagingReportFetchOneResponse
	 */
	public ImagingReport getImagingReport( ImagingReportFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ImagingReportFetchOneSummary arg cannot be null" );

		ImagingReport entity = null;
		UUID id = summary.getImagingReportId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a ImagingReport using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


